<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>IdeaForum — Page Not Found</title>
    <meta
      name="description"
      content="IdeaForum 404 page to help visitors return to educational talks and conference content."
    />
    <style>
      :root {
        --brand-red: #eb0028;
        --text-primary: #121212;
        --text-secondary: #5c5c5c;
        --text-link: #777777;
        --bg: #ffffff;
        --surface-muted: #f3f4f6;
        --border: #dedede;
        --divider: #d9d9d9;
        --focus: #0f766e;
      }

      * { box-sizing: border-box; }

      body {
        margin: 0;
        font-family: Inter, "DM Sans", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background: var(--bg);
        color: var(--text-primary);
        min-height: 100vh;
      }

      .page {
        min-height: 100vh;
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 2.5rem 1.25rem 7.5rem;
      }

      .content {
        width: min(100%, 44rem);
        display: flex;
        flex-direction: column;
        align-items: center;
        text-align: center;
        gap: 1.25rem;
      }

      .logo-wrap { margin-bottom: 0.5rem; }

      .logo {
        font-size: clamp(2rem, 5vw, 3.2rem);
        letter-spacing: 0.02em;
        line-height: 1;
        margin: 0;
        font-weight: 700;
      }

      .logo .idea, .logo .forum { color: var(--brand-red); }
      .logo .missing {
        color: var(--brand-red);
        opacity: 0.65;
        border: 2px dashed var(--brand-red);
        border-radius: 0.2rem;
        display: inline-block;
        width: 0.9em;
        height: 0.95em;
        margin: 0 0.08em;
        transform: translateY(0.06em);
      }

      h2 {
        margin: 0;
        font-size: clamp(1.45rem, 2.4vw, 1.9rem);
        font-weight: 600;
        letter-spacing: 0.01em;
      }

      .suggestion {
        margin: 0;
        color: var(--text-secondary);
        font-size: 1rem;
        max-width: 34rem;
      }

      .search-form {
        margin-top: 0.25rem;
        width: min(100%, 36rem);
      }

      .search-wrap {
        display: flex;
        align-items: center;
        border: 1px solid var(--border);
        border-radius: 0.7rem;
        overflow: hidden;
        background: #fff;
      }

      .search-input {
        flex: 1;
        min-width: 0;
        border: 0;
        outline: none;
        padding: 0.95rem 1rem;
        font-size: 1rem;
        color: var(--text-primary);
        background: transparent;
      }

      .search-input::placeholder { color: #8c8c8c; }

      .search-btn {
        border: 0;
        background: transparent;
        color: #6b7280;
        width: 3.2rem;
        height: 3.1rem;
        display: grid;
        place-items: center;
        cursor: pointer;
      }

      .search-btn:hover { background: #f8fafc; color: #334155; }

      .search-wrap:focus-within {
        border-color: var(--focus);
        box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.14);
      }

      .error-code {
        margin-top: 0.5rem;
        width: min(100%, 36rem);
        background: var(--surface-muted);
        color: #686868;
        font-weight: 500;
        font-size: 0.98rem;
        padding: 0.72rem 1rem;
        border-radius: 0.5rem;
      }

      .divider {
        width: min(100%, 36rem);
        border: 0;
        border-top: 1px solid var(--divider);
        margin: 0.45rem 0 0;
      }

      .next {
        width: min(100%, 36rem);
        text-align: center;
        margin-top: 0.2rem;
      }

      .next h3 {
        margin: 0 0 0.9rem;
        font-size: 1rem;
        font-weight: 600;
      }

      .next-links {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 0.72rem;
      }

      .next-links a {
        color: var(--text-link);
        text-decoration: underline;
        text-underline-offset: 2px;
        font-size: 0.99rem;
      }

      .next-links a:hover,
      .next-links a:focus-visible {
        color: #4b5563;
        outline: none;
      }

      .cookie-banner {
        position: fixed;
        left: 0;
        right: 0;
        bottom: 0;
        background: #ffffff;
        border-top: 1px solid var(--border);
        padding: 0.9rem 1rem;
        box-shadow: 0 -6px 24px rgba(15, 23, 42, 0.06);
      }

      .cookie-inner {
        width: min(100%, 70rem);
        margin: 0 auto;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.9rem;
      }

      .cookie-text {
        margin: 0;
        color: #505050;
        font-size: 0.88rem;
        line-height: 1.45;
      }

      .cookie-text a { color: #6b7280; }

      .manage-btn {
        border: 1px solid #bfc4cb;
        background: #fff;
        color: #374151;
        border-radius: 0.55rem;
        padding: 0.58rem 0.88rem;
        font-size: 0.88rem;
        cursor: pointer;
        white-space: nowrap;
      }

      .manage-btn:hover { background: #f8fafc; }

      dialog {
        border: 0;
        border-radius: 0.75rem;
        width: min(95vw, 31rem);
        padding: 0;
        box-shadow: 0 22px 56px rgba(0, 0, 0, 0.22);
      }

      dialog::backdrop { background: rgba(15, 23, 42, 0.45); }

      .modal-body { padding: 1.2rem 1.2rem 1rem; }

      .modal-title {
        margin: 0;
        font-size: 1.15rem;
        font-weight: 600;
      }

      .modal-copy {
        margin: 0.6rem 0 1rem;
        color: #4b5563;
        font-size: 0.95rem;
      }

      .pref-row {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 0.62rem 0;
        border-top: 1px solid #ececec;
        font-size: 0.93rem;
      }

      .pref-row:first-of-type { border-top: 0; }

      .pref-row label { color: #111827; }

      .modal-actions {
        display: flex;
        justify-content: flex-end;
        gap: 0.6rem;
        margin-top: 1rem;
      }

      .btn {
        border: 1px solid #c8ccd3;
        border-radius: 0.5rem;
        padding: 0.52rem 0.8rem;
        font-size: 0.9rem;
        cursor: pointer;
        background: #fff;
      }

      .btn.primary {
        background: #0f766e;
        border-color: #0f766e;
        color: #fff;
      }

      @media (max-width: 700px) {
        .page { padding-top: 2rem; }
        .cookie-inner { flex-direction: column; align-items: flex-start; }
        .manage-btn { align-self: flex-end; }
      }
    </style>
  </head>
  <body>
    <main class="page" aria-labelledby="error-title">
      <section class="content">
        <div class="logo-wrap" aria-label="IdeaForum logo">
          <h1 class="logo"><span class="idea">ID</span><span class="missing" aria-hidden="true"></span><span class="forum">AFORUM</span></h1>
        </div>

        <h2 id="error-title">Sorry, we can't find that.</h2>
        <p class="suggestion">Perhaps we can help you find the content you're looking for:</p>

        <form class="search-form" id="searchForm" role="search" aria-label="Search IdeaForum">
          <div class="search-wrap">
            <input
              id="searchInput"
              class="search-input"
              name="q"
              type="search"
              placeholder="Search IdeaForum..."
              aria-label="Search IdeaForum"
              required
            />
            <button class="search-btn" type="submit" aria-label="Search">
              <svg width="19" height="19" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                <circle cx="11" cy="11" r="7" stroke="currentColor" stroke-width="2"></circle>
                <path d="M20 20L16.65 16.65" stroke="currentColor" stroke-width="2" stroke-linecap="round"></path>
              </svg>
            </button>
          </div>
        </form>

        <div class="error-code" aria-live="polite">HTTP Error 404</div>
        <hr class="divider" />

        <div class="next">
          <h3>What's next?</h3>
          <div class="next-links">
            <a href="./homepage.html">Go to the homepage</a>
            <a href="./help-desk.html">Visit our Help Desk</a>
          </div>
        </div>
      </section>
    </main>

    <aside class="cookie-banner" id="cookieBanner" role="region" aria-label="Cookie consent">
      <div class="cookie-inner">
        <p class="cookie-text">
          This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics,
          personalization, and targeted advertising. To learn more, view the following link:
          <a href="./privacy-policy.html" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
        </p>
        <button class="manage-btn" id="managePrefsBtn" type="button">Manage Preferences</button>
      </div>
    </aside>

    <dialog id="prefsDialog" aria-labelledby="prefsTitle">
      <form method="dialog" class="modal-body">
        <h2 id="prefsTitle" class="modal-title">Cookie & Privacy Preferences</h2>
        <p class="modal-copy">Choose which optional cookie categories IdeaForum can use.</p>

        <div class="pref-row">
          <label for="essential">Essential Cookies</label>
          <input id="essential" type="checkbox" checked disabled />
        </div>
        <div class="pref-row">
          <label for="analytics">Analytics</label>
          <input id="analytics" type="checkbox" checked />
        </div>
        <div class="pref-row">
          <label for="personalization">Personalization</label>
          <input id="personalization" type="checkbox" />
        </div>
        <div class="pref-row">
          <label for="ads">Targeted Advertising</label>
          <input id="ads" type="checkbox" />
        </div>

        <div class="modal-actions">
          <button class="btn" value="cancel">Cancel</button>
          <button class="btn primary" id="savePrefs" value="default">Save Preferences</button>
        </div>
      </form>
    </dialog>

    <script>
      const searchForm = document.getElementById('searchForm');
      const searchInput = document.getElementById('searchInput');
      const managePrefsBtn = document.getElementById('managePrefsBtn');
      const prefsDialog = document.getElementById('prefsDialog');
      const savePrefs = document.getElementById('savePrefs');
      const cookieBanner = document.getElementById('cookieBanner');

      searchForm.addEventListener('submit', (event) => {
        event.preventDefault();
        const query = searchInput.value.trim();
        if (!query) return;
        window.location.href = `./search-results.html?q=${encodeURIComponent(query)}`;
      });

      managePrefsBtn.addEventListener('click', () => {
        if (typeof prefsDialog.showModal === 'function') {
          prefsDialog.showModal();
        }
      });

      savePrefs.addEventListener('click', () => {
        localStorage.setItem('ideaforum_cookie_prefs_saved', 'true');
        cookieBanner.hidden = true;
      });

      if (localStorage.getItem('ideaforum_cookie_prefs_saved') === 'true') {
        cookieBanner.hidden = true;
      }
    </script>
  </body>
</html>
